import os
from taf.ul.trs_e2e_fw.lib.ems.netact.netact_base import NetactBase
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class CMOperations(NetactBase):

    def __init__(self):
        super(CMOperations, self).__init__()

    def export(self, **kwargs):
        file_name = kwargs.pop('file_name', 'exported_actual_config.xml')
        operation_type = kwargs.pop('operation_type', 'actual')
        dist_names = kwargs.pop('dist_names', self.bts_moc_id)
        file_format = kwargs.pop('file_format', 'RAML2')
        class_filter = kwargs.pop('class_filter', 'ALL_MOCS')
        logger.debug(class_filter)
        class_filter_exclude = kwargs.pop('class_filter_exclude', None)
        class_filter_include = kwargs.pop('class_filter_include', None)
        plan_name = kwargs.pop('plan_name', None)
        ui_values = kwargs.pop('ui_values', False)
        include_site_info = kwargs.pop('include_site_info', False)
        logger.debug(include_site_info)
        include_maintenance_region_info = kwargs.pop('include_maintenance_region_info', False)
        logger.debug(include_maintenance_region_info)
        use_qualified_class_abbreviation = kwargs.pop('use_qualified_class_abbreviation', False)
        logger.debug(use_qualified_class_abbreviation)
        ignore_errors = kwargs.pop('ignore_errors', False)
        timeout = kwargs.pop('timeout', 7200)
        alias = kwargs.pop('alias', 'default')
        local_dir = kwargs.pop('local_dir', None)
        if local_dir is not None:
            if not os.path.exists(local_dir):
                os.makedirs(local_dir)
        self.netact_factory.netact.export_configuration(local_dir=local_dir, file_name=file_name,
                                                        operation_type=operation_type, dist_names=dist_names,
                                                        file_format=file_format,
                                                        class_filter_exclude=class_filter_exclude,
                                                        class_filter_include=class_filter_include, plan_name=plan_name,
                                                        ui_values=ui_values,
                                                        ignore_errors=ignore_errors, timeout=timeout, alias=alias,
                                                        parameters={'-includeMaintenanceregionInfo': True,'-useQualifiedClassAbbreviation': True})
                                                        # parameters={'-classFilter': class_filter,
                                                        #            '-includeMaintenanceregionInfo':
                                                        #                include_maintenance_region_info,
                                                        #            '-useQualifiedClassAbbreviation':
                                                        #                use_qualified_class_abbreviation,
                                                        #            '-includeSiteInfo': include_site_info},
                                                        # ignore_errors=ignore_errors, timeout=timeout, alias=alias)
        return local_dir

    def delete_ne_data_from_configurator(self, **kwargs):
        """
            Deletes configuration data of network element(s) by given dist_names.

            WARNING:
                    NE data is deleted from actual, plan and reference configurations with child objects
                    and NE3S based network element(s) are unregistered from NetAct database.
                    Site templates with the given dist_names (or for child objects) are deleted.
                    NE data is not deleted from the network.
                    The operation cannot be undone.
            @Param kwargs:
                    dist_names ((string|list(string))) - Specifies the scope of the operation.
                    trigger_post_upload (bool) - Specifies if Post-upload operation should be triggered in workflow.
                                                 True by default.
                    delete_from_plans (bool) - Specifies if object hierarchy should be deleted from every plan they
                                               appears. True by default.
                    verbose (bool) - If True, returns more detailed output from executed operation.
                    schedule (string) - prepare_schedule method should be used to obtain correct value.
                    ignore_errors (bool) - If True, shows warnings instead of raising errors when operation fails.
                    timeout ((int|string)) - Timeout for executing operation.
                    alias (string) - Netact instance name. Default value is 'default'.
            Returns:
                Operation output.
        """

        dist_names = kwargs['dist_names']
        trigger_post_upload = kwargs.pop('trigger_post_upload', True)
        delete_from_plans = kwargs.pop('delete_from_plans', True)
        verbose = kwargs.pop('verbose', True)
        schedule = kwargs.pop('schedule', None)
        ignore_errors = kwargs.pop('ignore_errors', False)
        timeout = kwargs.pop('timeout', 7200)
        alias = kwargs.pop("alias", 'default')
        return self.netact_factory.netact.delete_ne_data_from_configurator(dist_names,
                                                                           trigger_post_upload=trigger_post_upload,
                                                                           delete_from_plans=delete_from_plans,
                                                                           verbose=verbose, schedule=schedule,
                                                                           ignore_errors=ignore_errors,
                                                                           timeout=timeout, alias=alias)

